module top;
  integer a, b, op, r;
  initial begin
    r = $fscanf(32'h8000_0000, "%d %d %d", a, b, op);
    while (r == 3) begin
      case (op)
        0: $display("%0d", a + b);
        1: $display("%0d", a - b);
        2: $display("%0d", a & b);
        3: $display("%0d", a | b);
        default: $display("error");
      endcase
      r = $fscanf(32'h8000_0000, "%d %d %d", a, b, op);
    end
    $finish;
  end
endmodule
